import{_ as a,c as t,o as i,af as n}from"./chunks/framework.DeiWFBFB.js";const u=JSON.parse('{"title":"Referencing Native Federation Modules","description":"","frontmatter":{},"headers":[],"relativePath":"guide/formats/native-federation.md","filePath":"guide/formats/native-federation.md","lastUpdated":1791988773000}'),s={name:"guide/formats/native-federation.md"};function r(o,e,d,l,h,c){return i(),t("div",null,e[0]||(e[0]=[n(`<h1 id="referencing-native-federation-modules" tabindex="-1">Referencing Native Federation Modules <a class="header-anchor" href="#referencing-native-federation-modules" aria-label="Permalink to &quot;Referencing Native Federation Modules&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><a href="https://github.com/angular-architects/module-federation-plugin/tree/main/libs/native-federation" target="_blank" rel="noreferrer">Native Federation</a> brings the mental model of Module Federation to web standards. Micro frontends are plain ES modules, described by a <code>remoteEntry.json</code> that lists the exposed modules and the shared dependencies. Because it doesn&#39;t depend on a specific bundler, any build tool producing ES modules can create Native Federation micro frontends.</p><h2 id="using-native-federation" tabindex="-1">Using Native Federation <a class="header-anchor" href="#using-native-federation" aria-label="Permalink to &quot;Using Native Federation&quot;">​</a></h2><p>Native Federation modules can be used either as part of a discovery service response or directly by referencing a component using a <code>source</code> with <code>format</code> set to <code>native</code>.</p><h3 id="native-federation" tabindex="-1">Native Federation <a class="header-anchor" href="#native-federation" aria-label="Permalink to &quot;Native Federation&quot;">​</a></h3><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-component</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyComponent&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://yourcompany.com/example/remoteEntry.json&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;native&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">pi-component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Required:</p><ul><li><code>format</code> has to be set to <code>native</code></li></ul><h2 id="server-side-rendering" tabindex="-1">Server-Side Rendering <a class="header-anchor" href="#server-side-rendering" aria-label="Permalink to &quot;Server-Side Rendering&quot;">​</a></h2><p>Native Federation micro frontends can be rendered on the server, too. As they are ES modules, the <a href="./../variants/node">Node.js variant</a> evaluates them with <code>vm.SourceTextModule</code>, which requires <code>--experimental-vm-modules</code> in Node.js. Bun and Deno support it without a flag.</p><h2 id="content-security-policy" tabindex="-1">Content Security Policy <a class="header-anchor" href="#content-security-policy" aria-label="Permalink to &quot;Content Security Policy&quot;">​</a></h2><p>In the browser, Picard.js evaluates ES modules via <code>blob:</code> scripts to resolve their shared dependencies. Under a Content Security Policy forbidding <code>blob:</code> scripts (e.g., in browser extensions), modules without shared dependencies are imported directly instead.</p><p>👉 The <a href="https://github.com/picardjs/samples/tree/main/shared/nf-ssr-html" target="_blank" rel="noreferrer"><code>nf-ssr-html</code></a> micro frontend of the samples is a minimal Native Federation micro frontend that is rendered on the server by the <a href="https://github.com/picardjs/samples/tree/main/bun/ssr" target="_blank" rel="noreferrer">Bun</a> and <a href="https://github.com/picardjs/samples/tree/main/deno/ssr" target="_blank" rel="noreferrer">Deno</a> samples.</p>`,14)]))}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
